INSERT INTO public.offerings VALUES ('913d4a21-3cd9-4d3f-b26c-ad76fa11a540', 'bde423b7-54ca-4b23-9df3-239b792af9c6', 'software', 'Phần mềm quản lý bán hàng iOrder', 'phan-mem-quan-ly-ban-hang-iorder', 'Phần mềm bán hàng cho nhà hàng, cà phê và bán lẻ: gọi món, thu ngân, kho, nhân viên và báo cáo trên một nền tảng.', '{"faq": [["Có dùng thử miễn phí không?", "Có, dùng thử đầy đủ tính năng trong 15 ngày."], ["Mất mạng có bán được không?", "Có, ứng dụng hoạt động ngoại tuyến và tự đồng bộ khi có mạng."]], "tags": ["F&B", "Bán lẻ"], "items": [{"href": "/lien-he", "title": "Đăng ký tư vấn"}, {"href": "/tin-tuc", "title": "Xem tin tức iOrder"}], "bestFor": "Nhà hàng, quán cà phê, cửa hàng bán lẻ và chuỗi nhiều chi nhánh", "metrics": ["10.000+ cửa hàng sử dụng", "Triển khai trong 1 ngày"], "pricing": {"note": "Giá tham khảo (dữ liệu mẫu), chưa gồm VAT — cập nhật trước khi phát hành.", "plans": [{"name": "Cơ bản", "badge": null, "price": "199.000đ", "action": {"href": "https://app.iorder.vn/register-trial", "label": "Dùng thử"}, "period": "/tháng", "features": ["1 chi nhánh", "Bán hàng tại quầy", "Báo cáo cơ bản"], "description": "Cho cửa hàng nhỏ, một quầy.", "highlighted": false}, {"name": "Chuyên nghiệp", "badge": "Phổ biến", "price": "399.000đ", "action": {"href": "https://app.iorder.vn/register-trial", "label": "Dùng thử"}, "period": "/tháng", "features": ["1 chi nhánh", "Gọi món bằng QR", "Quản lý kho theo công thức", "Báo cáo nâng cao"], "description": "Cho nhà hàng, quán cà phê.", "highlighted": true}, {"name": "Chuỗi", "badge": null, "price": "Liên hệ", "action": {"href": "/lien-he", "label": "Nhận tư vấn"}, "period": null, "features": ["Không giới hạn chi nhánh", "Đồng bộ thực đơn và giá", "Hỗ trợ ưu tiên"], "description": "Cho chuỗi nhiều chi nhánh.", "highlighted": false}], "title": "Bảng giá phần mềm quản lý bán hàng iOrder", "eyebrow": "Bảng giá", "description": "Dùng thử miễn phí 15 ngày trước khi chọn gói."}, "benefits": ["Giảm thời gian thanh toán", "Kiểm soát thất thoát nguyên liệu", "Chủ cửa hàng theo dõi mọi lúc mọi nơi"], "category": "Quản lý bán hàng", "features": ["Bán hàng tại quầy và gọi món tại bàn", "Gọi món bằng QR", "Quản lý kho theo công thức món", "Báo cáo doanh thu theo thời gian thực", "Quản lý nhiều chi nhánh"], "keyValue": "Bán nhanh hơn, thất thoát ít hơn, ra quyết định bằng số liệu thật", "description": "iOrder giúp cửa hàng bán nhanh tại quầy, gọi món tại bàn, quản lý kho theo công thức, chấm công nhân viên và xem báo cáo theo thời gian thực trên mọi thiết bị."}', 'store', 'published', 4, 0, true, 'Phần mềm quản lý bán hàng iOrder', 'Phần mềm bán hàng cho nhà hàng, cà phê và bán lẻ: gọi món, thu ngân, kho, nhân viên và báo cáo trên một nền tảng.', NULL, NULL, '2026-10-21 09:55:06.58+00', NULL, '2026-10-21 08:04:05.708938+00', '2026-10-22 04:58:30.81+00');
