INSERT INTO public.offerings VALUES ('39e9da8d-3aa5-443d-a126-71a9bea584dd', '50578164-3061-4d64-a59f-3a6138a93aad', 'software', 'Phần mềm quản lý trạm sạc xe điện iOrder EV', 'phan-mem-quan-ly-tram-sac-xe-dien-iorder-ev', 'Quản lý trạm sạc xe điện: theo dõi trụ sạc, phiên sạc, thanh toán và doanh thu theo thời gian thực.', '{"faq": [["Hỗ trợ những loại trụ sạc nào?", "Các trụ sạc hỗ trợ giao thức OCPP phổ biến."], ["Khách thanh toán thế nào?", "Quét mã QR tại trụ sạc và thanh toán qua ví hoặc ngân hàng."]], "tags": ["Xe điện", "IoT"], "items": [{"href": "/lien-he", "title": "Đăng ký tư vấn"}, {"href": "/tin-tuc", "title": "Xem tin tức iOrder"}], "bestFor": "Chủ trạm sạc, bãi đỗ xe, khu đô thị và chuỗi cửa hàng có trạm sạc", "metrics": ["Giám sát 24/7", "Thanh toán không tiền mặt"], "benefits": ["Giảm chi phí nhân sự trực trạm", "Minh bạch doanh thu theo từng trụ"], "category": "Trạm sạc xe điện", "features": ["Theo dõi trạng thái trụ sạc", "Thanh toán QR theo phiên sạc", "Báo cáo sản lượng điện và doanh thu", "Cảnh báo lỗi trụ sạc"], "keyValue": "Vận hành trạm sạc không cần người trực", "description": "iOrder EV kết nối các trụ sạc, ghi nhận từng phiên sạc, tính tiền tự động và cho chủ trạm xem trạng thái toàn bộ hệ thống trên một màn hình."}', 'plug-zap', 'published', 2, 1, true, 'Phần mềm quản lý trạm sạc xe điện iOrder EV', 'Quản lý trạm sạc xe điện: theo dõi trụ sạc, phiên sạc, thanh toán và doanh thu theo thời gian thực.', NULL, NULL, '2026-10-21 10:03:27.304+00', NULL, '2026-10-21 08:04:05.753017+00', '2026-10-21 10:03:27.305+00');
INSERT INTO public.offerings VALUES ('420845de-85f0-4d44-87a1-095e77318bff', '03cf1ce7-6b80-4db6-a8d8-34d5406449cb', 'software', 'Hóa đơn điện tử - Chữ ký số', 'hoa-don-dien-tu-chu-ky-so', 'Xuất hóa đơn điện tử ngay khi bán hàng, ký số và gửi cho khách theo đúng quy định.', '{"faq": [["Có phải mua chữ ký số riêng không?", "iOrder hỗ trợ đăng ký chữ ký số cùng gói hóa đơn điện tử."], ["Hóa đơn có đúng quy định không?", "Hóa đơn tuân theo quy định hiện hành về hóa đơn điện tử."]], "tags": ["Hóa đơn điện tử"], "items": [{"href": "/lien-he", "title": "Đăng ký tư vấn"}, {"href": "/tin-tuc", "title": "Xem tin tức iOrder"}], "bestFor": "Doanh nghiệp, hộ kinh doanh phải xuất hóa đơn điện tử", "metrics": ["Xuất hóa đơn dưới 5 giây"], "benefits": ["Không nhập lại dữ liệu", "Tránh sai sót khi xuất hóa đơn"], "category": "Hóa đơn & chữ ký số", "features": ["Xuất hóa đơn từ đơn bán hàng", "Ký số tự động", "Gửi hóa đơn qua email", "Tra cứu hóa đơn"], "keyValue": "Xuất hóa đơn trong vài giây, đúng quy định", "description": "Kết nối iOrder với nhà cung cấp hóa đơn điện tử để xuất hóa đơn từ đơn bán hàng, ký bằng chữ ký số và gửi email cho khách tự động."}', 'file-check', 'published', 2, 2, true, 'Hóa đơn điện tử - Chữ ký số', 'Xuất hóa đơn điện tử ngay khi bán hàng, ký số và gửi cho khách theo đúng quy định.', NULL, NULL, '2026-10-21 10:03:27.328+00', NULL, '2026-10-21 08:04:05.773578+00', '2026-10-21 10:03:27.329+00');
INSERT INTO public.offerings VALUES ('6a03bf2d-bc5e-4b25-b6d5-27646185283d', 'c0f93297-80ca-4c65-9cb3-1f8f74eb8a07', 'service', 'Phát triển phần mềm theo yêu cầu', 'phat-trien-phan-mem-theo-yeu-cau', 'Xây dựng phần mềm, ứng dụng di động và tích hợp hệ thống theo đúng nghiệp vụ riêng của doanh nghiệp.', '{"faq": [["Doanh nghiệp có sở hữu mã nguồn không?", "Có, tùy theo thỏa thuận hợp đồng."], ["Có bảo trì sau bàn giao không?", "Có gói bảo trì định kỳ sau bàn giao."]], "tags": ["Phần mềm", "Tích hợp"], "items": [{"href": "/lien-he", "title": "Đăng ký tư vấn"}, {"href": "/tin-tuc", "title": "Xem tin tức iOrder"}], "bestFor": "Doanh nghiệp có quy trình đặc thù chưa có phần mềm đóng gói phù hợp", "metrics": ["Báo giá trong 7 ngày"], "benefits": ["Tự động hóa quy trình riêng", "Mở rộng theo nhu cầu"], "category": "Phát triển phần mềm", "features": ["Phân tích và thiết kế nghiệp vụ", "Ứng dụng web và di động", "Tích hợp API với hệ thống sẵn có", "Bảo trì và nâng cấp"], "keyValue": "Phần mềm vừa khít quy trình, sở hữu mã nguồn", "description": "Từ phân tích yêu cầu, thiết kế giao diện tới phát triển, kiểm thử và bảo trì, iOrder xây dựng phần mềm theo nghiệp vụ đặc thù và tích hợp với hệ thống sẵn có."}', 'code', 'published', 2, 4, false, 'Phát triển phần mềm theo yêu cầu', 'Xây dựng phần mềm, ứng dụng di động và tích hợp hệ thống theo đúng nghiệp vụ riêng của doanh nghiệp.', NULL, NULL, '2026-10-21 10:03:27.373+00', NULL, '2026-10-21 08:04:05.815667+00', '2026-10-21 10:03:27.374+00');
