INSERT INTO public.page_blocks VALUES ('570c9d67-7b0b-4aed-9af4-9b09577a2613', '397aff2a-d399-4c4b-ac74-638af0a694df', 'ecosystem', 2, '{"items": [{"href": "/phan-mem", "title": "Phần mềm quản lý", "description": "Quản lý bán hàng cho nhà hàng, cà phê, bán lẻ; quản lý trạm sạc xe điện; hóa đơn điện tử và chữ ký số."}, {"href": "/giai-phap", "title": "Giải pháp hạ tầng", "description": "Thiết kế và thi công mạng, Wifi, camera; data center; kiểm soát ra vào và chấm công."}, {"href": "/dich-vu", "title": "Dịch vụ công nghệ", "description": "Tư vấn chuyển đổi số, phát triển phần mềm theo yêu cầu riêng của doanh nghiệp."}, {"href": "/thiet-bi", "title": "Thiết bị bán hàng", "description": "Máy POS, máy in hóa đơn, máy quét mã vạch, két tiền — đồng bộ sẵn với phần mềm iOrder."}], "title": "Bốn mảng giải pháp trên cùng một đầu mối", "eyebrow": "Hệ sinh thái iOrder", "description": "Chọn đúng phần bạn cần hoặc kết hợp nhiều giải pháp — iOrder tư vấn, triển khai và hỗ trợ xuyên suốt."}', NULL, true, '2026-10-22 10:23:04.888827+00', '2026-10-22 10:23:04.888827+00');
