INSERT INTO public.posts VALUES ('f0528974-2937-4c2f-a94f-3b3f2e9ce7bc', NULL, '0e753a61-1899-475d-9796-583747d19742', 'news', 'iOrder ra mắt giao diện bán hàng mới, thao tác nhanh hơn 30%', 'iorder-ra-mat-giao-dien-ban-hang-moi', 'Giao diện bán hàng mới giúp thu ngân lên đơn, tách bàn và thanh toán chỉ với vài lần chạm.', '{"doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Phiên bản mới của iOrder tập trung vào tốc độ thao tác tại quầy: thu ngân lên đơn, gộp bàn, tách hóa đơn và thanh toán nhanh hơn.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Những thay đổi chính", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Màn hình gọi món gọn hơn, tìm món theo tên hoặc mã", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tách và gộp bàn chỉ với hai lần chạm", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thanh toán QR hiện ngay trên màn hình khách", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Cập nhật như thế nào?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bản cập nhật tự động áp dụng cho mọi cửa hàng, không cần cài đặt lại. Dữ liệu bán hàng được giữ nguyên.", "type": "text"}]}]}, "version": 2}', NULL, 'published', 1, 0, 'iOrder ra mắt giao diện bán hàng mới, thao tác nhanh hơn 30%', 'Giao diện bán hàng mới giúp thu ngân lên đơn, tách bàn và thanh toán chỉ với vài lần chạm.', NULL, NULL, NULL, 'Dùng thử miễn phí', 'https://app.iorder.vn/register-trial', 'Mới', NULL, '2026-10-21 10:03:26.997+00', NULL, '2026-10-21 10:03:26.999214+00', '2026-10-21 10:03:26.999214+00');
INSERT INTO public.posts VALUES ('785d2127-1720-425d-a095-def331338bf9', NULL, '67348cd0-265d-4db9-9507-302e7a044c5a', 'news', '5 cách giảm thời gian chờ món vào giờ cao điểm', '5-cach-giam-thoi-gian-cho-mon-gio-cao-diem', 'Giờ cao điểm là lúc dễ mất khách nhất. Năm cách đơn giản giúp bếp và phục vụ phối hợp nhịp nhàng hơn.', '{"doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Khách chờ món quá lâu là lý do hàng đầu khiến họ không quay lại. Dưới đây là năm cách các cửa hàng dùng iOrder đã áp dụng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "1. Gửi món thẳng xuống bếp", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Đơn được in hoặc hiện trên màn hình bếp ngay khi phục vụ bấm gửi, không cần chạy phiếu tay.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "2. Chuẩn bị trước món bán chạy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Báo cáo món bán chạy theo khung giờ giúp bếp sơ chế trước.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "3. Gọi món tại bàn bằng QR", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Khách tự gọi món, nhân viên chỉ cần xác nhận.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "4. Theo dõi thời gian chế biến", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Mỗi món có đồng hồ đếm từ lúc gọi tới lúc ra món.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "5. Phân khu phục vụ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Chia bàn theo khu vực để mỗi nhân viên phụ trách rõ ràng.", "type": "text"}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Áp dụng gọi món bằng QR, thời gian chờ của quán giảm gần một nửa vào cuối tuần.", "type": "text"}]}]}]}, "version": 2}', NULL, 'published', 1, 0, '5 cách giảm thời gian chờ món vào giờ cao điểm', 'Giờ cao điểm là lúc dễ mất khách nhất. Năm cách đơn giản giúp bếp và phục vụ phối hợp nhịp nhàng hơn.', NULL, NULL, NULL, 'Nhận tư vấn', 'https://iorder.com.vn/lien-he', 'Kinh nghiệm', NULL, '2026-10-21 10:03:27.046+00', NULL, '2026-10-21 10:03:27.048401+00', '2026-10-21 10:03:27.048401+00');
INSERT INTO public.posts VALUES ('c331ac78-fac3-4f21-aa34-adde59d7d22c', NULL, 'dc44039a-d2d9-4e0a-8ab1-7906202ab7cb', 'promotion', 'Ưu đãi tháng này: đăng ký gói năm tặng máy in hóa đơn', 'uu-dai-mua-phan-mem-tang-may-in', 'Đăng ký gói 12 tháng trong tháng này để nhận máy in hóa đơn nhiệt và miễn phí cài đặt tại cửa hàng.', '{"doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Chương trình áp dụng cho khách hàng đăng ký mới gói 12 tháng trong thời gian khuyến mãi.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Quà tặng", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Máy in hóa đơn nhiệt khổ 80mm", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Miễn phí cài đặt và đào tạo tại cửa hàng", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tặng thêm 1 tháng sử dụng", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Điều kiện", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Mỗi cửa hàng nhận tối đa một phần quà. Chương trình có thể kết thúc sớm khi hết quà.", "type": "text"}]}]}, "version": 2}', NULL, 'published', 1, 0, 'Ưu đãi tháng này: đăng ký gói năm tặng máy in hóa đơn', 'Đăng ký gói 12 tháng trong tháng này để nhận máy in hóa đơn nhiệt và miễn phí cài đặt tại cửa hàng.', NULL, '2026-10-18 10:03:24.395+00', '2026-11-17 10:03:24.395+00', 'Đăng ký ngay', 'https://app.iorder.vn/register-trial', 'Ưu đãi', NULL, '2026-10-21 10:03:27.078+00', NULL, '2026-10-21 10:03:27.080117+00', '2026-10-21 10:03:27.080117+00');
INSERT INTO public.posts VALUES ('e641c78c-9c6d-4554-8a5e-22b6a9ab9fd8', NULL, '6d50582c-0d34-458f-8cb3-bc8b69445181', 'case_study', 'Chuỗi cà phê quản lý 10 chi nhánh trên một màn hình', 'chuoi-ca-phe-quan-ly-10-chi-nhanh', 'Từ sổ sách rời rạc ở từng quán tới báo cáo tập trung theo thời gian thực cho chủ chuỗi.', '{"doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Trước khi dùng iOrder, mỗi chi nhánh tự ghi chép doanh thu và tồn kho, cuối ngày gửi báo cáo qua tin nhắn.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Thách thức", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Không biết doanh thu thật theo thời gian thực", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thất thoát nguyên liệu khó kiểm soát", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Giá bán và khuyến mãi không đồng bộ giữa các quán", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Giải pháp", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Toàn bộ chi nhánh dùng chung thực đơn, giá và chương trình khuyến mãi; kho được trừ tự động theo công thức món.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Kết quả", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Chủ chuỗi xem doanh thu từng quán trên điện thoại, thất thoát nguyên liệu giảm rõ rệt sau ba tháng.", "type": "text"}]}]}, "version": 2}', NULL, 'published', 1, 0, 'Chuỗi cà phê quản lý 10 chi nhánh trên một màn hình', 'Từ sổ sách rời rạc ở từng quán tới báo cáo tập trung theo thời gian thực cho chủ chuỗi.', NULL, NULL, NULL, 'Tư vấn cho chuỗi', 'https://iorder.com.vn/lien-he', 'Câu chuyện khách hàng', NULL, '2026-10-21 10:03:27.108+00', NULL, '2026-10-21 10:03:27.109842+00', '2026-10-21 10:03:27.109842+00');
INSERT INTO public.posts VALUES ('151ba16b-225b-452d-93fd-97efd0423612', NULL, '03cf1ce7-6b80-4db6-a8d8-34d5406449cb', 'announcement', 'Thông báo lịch bảo trì hệ thống định kỳ', 'thong-bao-lich-bao-tri-he-thong', 'Hệ thống bảo trì định kỳ vào rạng sáng Chủ nhật; ứng dụng bán hàng vẫn hoạt động ngoại tuyến.', '{"doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Để nâng cấp hạ tầng, iOrder bảo trì hệ thống định kỳ từ 01:00 tới 03:00 sáng Chủ nhật.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Ảnh hưởng", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ứng dụng bán hàng vẫn hoạt động ngoại tuyến", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Báo cáo trên web có thể chậm trong thời gian bảo trì", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dữ liệu tự đồng bộ khi hệ thống hoạt động lại", "type": "text"}]}]}]}]}, "version": 2}', NULL, 'published', 1, 0, 'Thông báo lịch bảo trì hệ thống định kỳ', 'Hệ thống bảo trì định kỳ vào rạng sáng Chủ nhật; ứng dụng bán hàng vẫn hoạt động ngoại tuyến.', NULL, NULL, NULL, 'Liên hệ hỗ trợ', 'https://iorder.com.vn/lien-he', 'Thông báo', NULL, '2026-10-21 10:03:27.14+00', NULL, '2026-10-21 10:03:27.141766+00', '2026-10-21 10:03:27.141766+00');
INSERT INTO public.posts VALUES ('7dc329ef-86a2-43b1-8315-47b6d5236a27', NULL, '03cf1ce7-6b80-4db6-a8d8-34d5406449cb', 'guide', 'Hướng dẫn tạo thực đơn và giá bán', 'huong-dan-tao-thuc-don-va-gia-ban', 'Tạo nhóm món, món, giá theo size và topping trong vài phút.', '{"doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Thực đơn là dữ liệu đầu tiên cần chuẩn bị trước khi bán hàng.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Bước 1: Tạo nhóm món", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Vào Hàng hóa → Nhóm hàng → Thêm nhóm, ví dụ: Cà phê, Trà, Bánh.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Bước 2: Thêm món", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Vào Hàng hóa → Thêm hàng hóa, nhập tên, giá bán và chọn nhóm.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Bước 3: Giá theo size và topping", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thêm thuộc tính Size với giá cộng thêm", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Thêm topping dùng chung cho nhiều món", "type": "text"}]}]}]}]}, "version": 2}', NULL, 'published', 1, 0, 'Hướng dẫn tạo thực đơn và giá bán', 'Tạo nhóm món, món, giá theo size và topping trong vài phút.', NULL, NULL, NULL, 'Xem video hướng dẫn', 'https://www.youtube.com/results?search_query=iorder+huong+dan', 'Cơ bản', NULL, '2026-10-21 10:03:27.174+00', NULL, '2026-10-21 10:03:27.175677+00', '2026-10-21 10:03:27.175677+00');
INSERT INTO public.posts VALUES ('e1e2e7ad-2ff4-4a88-8066-92766493da0d', NULL, '8b2ccc37-bc9b-4dc4-836d-e7b1fe7debe2', 'guide', 'Hướng dẫn cài đặt máy in hóa đơn', 'huong-dan-cai-dat-may-in-hoa-don', 'Kết nối máy in nhiệt qua USB hoặc mạng LAN và in thử hóa đơn.', '{"doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "iOrder hỗ trợ máy in nhiệt khổ 58mm và 80mm qua USB, LAN và Bluetooth.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Cài driver", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tải driver đúng dòng máy tại mục Hỗ trợ cài đặt và cài như phần mềm thông thường.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Kết nối trong iOrder", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Vào Thiết lập → Máy in → Thêm máy in", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Chọn kiểu kết nối và khổ giấy", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bấm In thử để kiểm tra", "type": "text"}]}]}]}]}, "version": 2}', NULL, 'published', 1, 0, 'Hướng dẫn cài đặt máy in hóa đơn', 'Kết nối máy in nhiệt qua USB hoặc mạng LAN và in thử hóa đơn.', NULL, NULL, NULL, 'Tải driver máy in', 'https://iorder.com.vn/ho-tro/cai-dat', 'Thiết bị', NULL, '2026-10-21 10:03:27.204+00', NULL, '2026-10-21 10:03:27.206025+00', '2026-10-21 10:03:27.206025+00');
INSERT INTO public.posts VALUES ('577f549c-f051-45d3-918d-26a4f696284e', NULL, 'c0f93297-80ca-4c65-9cb3-1f8f74eb8a07', 'guide', 'Hướng dẫn xem báo cáo doanh thu', 'huong-dan-xem-bao-cao-doanh-thu', 'Xem doanh thu theo ngày, ca, nhân viên và món bán chạy.', '{"doc": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Báo cáo cập nhật theo thời gian thực trên máy tính và điện thoại.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Các loại báo cáo", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Doanh thu theo ngày, tuần, tháng", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Doanh thu theo ca và nhân viên", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Món bán chạy và món bán chậm", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Xuất báo cáo", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bấm Xuất Excel ở góc phải để tải báo cáo về máy.", "type": "text"}]}]}, "version": 2}', NULL, 'published', 1, 0, 'Hướng dẫn xem báo cáo doanh thu', 'Xem doanh thu theo ngày, ca, nhân viên và món bán chạy.', NULL, NULL, NULL, 'Mở ứng dụng', 'https://app.iorder.vn/login', 'Báo cáo', NULL, '2026-10-21 10:03:27.232+00', NULL, '2026-10-21 10:03:27.233823+00', '2026-10-21 10:03:27.233823+00');
